export function classifyMuscle(name){
 const n=name.toLowerCase().replaceAll('_',' ');if(/tendon|aponeurosis|retinaculum|fascia/.test(n))return null;
 const groups={upperchest:/clavicular part of .*pectoralis major/,sternchest:/sternocostal part of .*pectoralis major/,pecminor:/pectoralis minor/,frontdelts:/clavicular part of .*deltoid/,sidedelts:/acromial part of .*deltoid/,reardelts:/spinal part of .*deltoid/,bicepslong:/long head of .*biceps brachii/,bicepsshort:/short head of .*biceps brachii/,tricepslong:/long head of .*triceps brachii/,tricepslateral:/lateral head of .*triceps brachii/,tricepsmedial:/medial head of .*triceps brachii/,rectusfemoris:/rectus femoris/,vastuslateralis:/vastus lateralis/,vastusmedialis:/vastus medialis/,vastusintermedius:/vastus intermedius/,femorislong:/long head of .*biceps femoris/,femorisshort:/short head of .*biceps femoris/,semitendinosus:/semitendinosus/,semimembranosus:/semimembranosus/,gluteMax:/gluteus maximus/,gluteabductors:/gluteus (medius|minimus)/,rectusabs:/rectus abdominis/,transverseabs:/transversus abdominis/,obliques:/(external|internal) oblique/,gastromedial:/medial head of .*gastrocnemius/,gastrolateral:/lateral head of .*gastrocnemius/,soleus:/soleus/,adductorlongus:/adductor longus/,adductormagnus:/adductor magnus/,adductorbrevis:/adductor brevis/,traps:/trapezius/,lats:/latissimus/,rhomboids:/rhomboid/,erectors:/erector|iliocostalis|longissimus|spinalis|multifidus/,serratus:/serratus anterior/,forearms:/brachioradialis|pronator|supinator|flexor carpi|extensor carpi|palmaris longus/,chest:/pectoralis/,shoulders:/deltoid/,biceps:/biceps brachii|brachialis/,triceps:/triceps brachii|anconeus/,abs:/rectus abdominis|transversus abdominis/,back:/teres|infraspinatus|supraspinatus/,glutes:/gluteus|piriformis/,quads:/rectus femoris|vastus/,hamstrings:/biceps femoris|semitendinosus|semimembranosus/,calves:/gastrocnemius/,adductors:/adductor.*(brevis|longus|magnus)|gracilis|pectineus/};
 return Object.keys(groups).find(k=>groups[k].test(n))||null;
}
